CREATE PROCEDURE CLAIMS.SUMMARIZE_CUSTOMER
(
    IN P_CUSTOMER_ID BIGINT,
    OUT P_TOTAL DECIMAL(15,2)
)
LANGUAGE SQL
BEGIN
    DECLARE V_TOTAL DECIMAL(15,2) DEFAULT 0;
    DECLARE V_AMOUNT DECIMAL(15,2);
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET V_AMOUNT = 0;

    FOR C1 AS
        SELECT C.AMOUNT
          FROM CLAIM C
          LEFT JOIN PAYMENT P ON P.CLAIM_ID = C.CLAIM_ID
         WHERE C.CUSTOMER_ID = P_CUSTOMER_ID
    DO
        SET V_TOTAL = V_TOTAL + C1.AMOUNT;
    END FOR;

    SET P_TOTAL = V_TOTAL;
END;
